import React, { useEffect, useState } from "react";

import { getStore, updStore, gen16CodeId, copyToClipboard, hasWritePrivilege, getQrcode, ObjectKeys, AccountYears } from "../../../stores/Utils";

import "./dashboard.css"
import {     ViewSubMayor_Cmpt,  ViewVoucher_Cmpt } from "..";
import { OpenModal } from "../../../components/DialogHRM";
import {  sortProducts } from "../services/server_fetching";
import { SvgIcon_Cmpt, LoadingColorSpinner_Cmpt} from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";
import { VoucherPdf } from "../services/export_service";

import * as htmlToImage from 'html-to-image';
import { LeftLShapeScketch, UShapeScketch } from "../content/Typesframes";


const Svg = SvgIcon_Cmpt();

const ViewVoucher = ViewVoucher_Cmpt();

const ViewSubMayor = ViewSubMayor_Cmpt();

const LoadingColorSpinner = LoadingColorSpinner_Cmpt();


const frmNm = "view_voucher"


const productListOn = "productListOnVoucherCmp"



const ProductVoucherItem  = ({ data, elmId, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [loadPrint, setLoadPrint] = useState(false);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}



	const refreshAccs =  () => {
		// getall_product(updObs)
	}

	const update = async () => {
		if(hasWritePrivilege()){

			updStore(frmNm, data);
			updStore(frmNm+"_bck", JSON.parse(JSON.stringify(data)));
			updStore(productListOn, data.products);
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			modaldata["content"] = <ViewVoucher confirm={refreshAccs} updateView={true}/>;
			OpenModal(modaldata);
		}
	}

	
	


	const openSubMayor =  (sba) => {
		

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] = 
			<ViewSubMayor confirm={refreshAccs} item={data}/>
		OpenModal(modaldata);
	}


	const deleteComprobante =  () => {
		//delete_product(data?.productId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert  label={"Eliminar Voucher"} confirm={deleteComprobante} item={data} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	let subAcc = sortProducts( getStore("sub_product_group")?.[data.productId],"subProduct");
	
	
	const copyToClpb  =  ()  => {
		copyToClipboard( data?. productCode);
	};


	
	const printInvLbs = async () => {
		setLoadPrint(true)
		updStore("bluePrint",null)
		let frm2 = data || {};

		let obj2Prnt = {
			invoice: frm2?.invoice,
			date: frm2?.date,
			clientAddress: frm2?.clientAddress,
			clientName: frm2?.clientName,
			products: [],
			locProdFinish: []
		}

		
		let date = (new Date()).getTime()+800;
		if(obj2Prnt["date"]){
			let nn = (new Date(obj2Prnt["date"])).getTime();
			date = nn?nn:date;
		}
		obj2Prnt["date"] = date; 


		const pngUrl = getQrcode(frm2?.voucherId+"");
		obj2Prnt["voucherIdQR"] = pngUrl;

		let lll = "";
		data?.["locProdFinish"]  && ObjectKeys(data?.["locProdFinish"]).map((locId, indE)=>{
			let locItm = getStore("locations_ids")?.[locId];
			let locFnsh = data?.["locProdFinish"]?.[locId];

			let alphB = 6;
			if(indE === 0){
				lll += `${locItm?.areaId}-${locItm?.location}`
			}
			else if(indE === ObjectKeys(data?.["locProdFinish"]).length-1){
				if(locFnsh){
					lll += `  |  ${locItm?.areaId}-${locItm?.location}`
				}
				obj2Prnt.locProdFinish.push(lll);
				lll = "";
			}
			else if(indE >0 && indE%alphB === 0){
				obj2Prnt.locProdFinish.push(lll);
				lll = "";
				if(locFnsh){
					lll += `${locItm?.areaId}-${locItm?.location}`
				}
			}
			else if(locFnsh){
				lll += `  |  ${locItm?.areaId}-${locItm?.location}`
			}
		})


		const promises = data.products.map(async (item) => {
			let productD = getStore("products_ids")?.[item?.productId];
			let nOvj = {}
			nOvj["productName"] = productD?.name;
			nOvj["qty"] = item?.qty*1;
			nOvj["profile"] = item?.profile;


			if(item?.bluePrint?.type){
				//let gg = document.getElementById(item.productId +"_"+ item?.bluePrint?.type);
				//let dataUrl = await htmlToImage.toPng(gg);
				//nOvj["pngId"] = dataUrl;
			}
			obj2Prnt.products.push(nOvj);
		})
		const contents = await Promise.all(promises);
		
		
		let pdfUri = await VoucherPdf(obj2Prnt);


		//let pdfUri = await generateTemp("I485_form.pdf", 1)
		setLoadPrint(false)
		window.open(pdfUri);
	}


	return (
		<div className="item_acc">
			<div className="_dsplFlx item_box product_header">
				<div className="_dsplFlx">
					<div className="code centerBx"  onClick={()=>update()} >
						{data?. invoice}
					</div>
					<div className="name centerBx"  >
						{data?. clientName }
					</div>
				</div>
				<div className="flexSpace"/>
				<div className=" addSbAcc purple centerBx" onClick={()=>printInvLbs(null)}>
					{loadPrint ? 
						<div className="icon_compr _dsplFlx centerBx">
							<div className="lbl_saving ">
									generating report ... 
							</div>
							<LoadingColorSpinner stroke={"var(--partial-success)"} size={24} strokeW={8}/>
						</div>:
						<div>Print</div>
					}
				</div>
				{hasWritePrivilege()?
				AccountYears()[getStore("date_current_year")]?.isClosed?null:
					<div className="icon" style={{marginLeft: 19}} onClick={OpenDeleteAlert}>
						<Svg name={"outline_delete"} color={"#c62828"}/>
					</div>
				:null}
			</div>
			<div className={"rndImghidde"}>
				{data.products && data.products?.map((item, indE)=>{
					const Cmp2Rend = {
							"LL": <LeftLShapeScketch key={indE+"_"+item?.productId} item={item} svDm={item?.bluePrint} addBlPr={()=>{}} profile={item?.profile} />,
							"U":<UShapeScketch key={indE+"_"+item?.productId} item={item} svDm={item?.bluePrint} addBlPr={()=>{}} profile={item?.profile}/>
					}
					if(!(item?.bluePrint?.type)){
						return null
					}
					return  (Cmp2Rend[item?.bluePrint?.type]);
				})}
			</div>
		</div>
	)
}
export default ProductVoucherItem;